DROP DATABASE IF EXISTS messy_retail_db;
CREATE DATABASE messy_retail_db;
USE messy_retail_db;

CREATE TABLE customers (
    CustomerID INT,
    FirstName TEXT,
    LastName VARCHAR(50),
    EmailAddress VARCHAR(100),
    PhoneNumber VARCHAR(20),
    AddressLine VARCHAR(200),
    City VARCHAR(50),
    State VARCHAR(20),
    Zip VARCHAR(10),
    status VARCHAR(20),
    created_date VARCHAR(50)
);

CREATE TABLE orders (
    order_id INT,
    customerId INT,
    orderDate VARCHAR(50),
    orderStatus VARCHAR(30),
    TotalAmount DECIMAL(10,2),
    store_id INT,
    employee_id INT
);

CREATE TABLE order_items (
    OrderItemID INT,
    OrderId INT,
    ProductID INT,
    Quantity TEXT,
    UnitPrice DECIMAL(10,2),
    Discount DECIMAL(5,2)
);

CREATE TABLE products (
    product_id INT,
    ProductName VARCHAR(100),
    SKU VARCHAR(20),
    descr TEXT,
    category VARCHAR(50),
    brand VARCHAR(50),
    supplierId INT,
    price DECIMAL(10,2),
    cost DECIMAL(10,2),
    ProductDescription TEXT
);

CREATE TABLE suppliers (
    SupplierID INT,
    supplier_name VARCHAR(100),
    ContactName VARCHAR(100),
    Phone VARCHAR(30),
    email VARCHAR(100),
    Address VARCHAR(200),
    City VARCHAR(50),
    State VARCHAR(20),
    ZipCode VARCHAR(10)
);

CREATE TABLE inventory (
    InventoryID INT,
    productId INT,
    storeId INT,
    qty VARCHAR(20),
    last_updated VARCHAR(50)
);

CREATE TABLE stores (
    StoreID INT,
    StoreName VARCHAR(100),
    address VARCHAR(200),
    city VARCHAR(50),
    state VARCHAR(20),
    zip VARCHAR(10),
    phone VARCHAR(30),
    managerId INT
);

CREATE TABLE employees (
    EmployeeID INT,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    email VARCHAR(100),
    phone VARCHAR(30),
    hire_date VARCHAR(50),
    position VARCHAR(50),
    storeId INT,
    manager_id INT
);

CREATE TABLE payments (
    PaymentID INT,
    OrderID INT,
    payment_date VARCHAR(50),
    amount TEXT,
    payment_method VARCHAR(30),
    PaymentStatus VARCHAR(20)
);

CREATE TABLE shipping (
    ShippingID INT,
    OrderID INT,
    ship_date VARCHAR(50),
    delivery_date VARCHAR(50),
    carrier VARCHAR(50),
    tracking_number VARCHAR(50),
    shipping_cost DECIMAL(10,2),
    ShipStatus VARCHAR(20)
);

SET FOREIGN_KEY_CHECKS = 0;












